import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_ops_kernel(
    const float* input,
    float* output,
    float bias,
    float scaling_factor,
    int num_elements,
    int channels,
    int D, int H, int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int b = idx / (D * H * W);
    int spatial = idx % (D * H * W);
    int d = spatial / (H * W);
    spatial %= (H * W);
    int h = spatial / W;
    int w = spatial % W;

    float sum = 0.0f;
    for(int c = 0; c < channels; ++c) {
        int input_idx = b * channels * D * H * W + 
                        c * D * H * W + 
                        d * H * W + 
                        h * W + 
                        w;
        sum += input[input_idx];
    }

    float val = sum / channels + bias;
    val = tanhf(val) * scaling_factor;
    output[idx] = val;
}

torch::Tensor fused_operations_cuda(
    torch::Tensor input,
    torch::Tensor bias,
    float scaling_factor
) {
    auto sizes = input.sizes();
    int batch_size = sizes[0];
    int channels = sizes[1];
    int D = sizes[2];
    int H = sizes[3];
    int W = sizes[4];

    auto output = torch::empty({batch_size, 1, D, H, W}, input.options());

    int num_elements = batch_size * D * H * W;
    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        bias.item<float>(),
        scaling_factor,
        num_elements,
        channels,
        D, H, W
    );

    return output;
}
"""

fused_kernel_cpp = """
torch::Tensor fused_operations_cuda(torch::Tensor input, torch::Tensor bias, float scaling_factor);
"""

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_code,
    functions=['fused_operations_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias_shape, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size, 
            stride=stride, padding=padding
        )
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scaling_factor = scaling_factor

    def forward(self, x):
        x = self.conv_transpose(x)
        x = fused_ops.fused_operations_cuda(x, self.bias, self.scaling_factor)
        return x
